<div class="section-heading"><div><div class="eyebrow">Agenda inteligente</div><h1>Lista de espera</h1><p class="text-secondary mb-0">Quando um horário abre, o sistema procura clientes compatíveis por serviço, profissional e período.</p></div></div>
<div class="card mb-4"><div class="card-body"><form method="post" action="/waitlist" class="row g-2"><?=
\App\Core\CSRF::field()?><div class="col-md-3"><select class="form-select" name="customer_id" required><option value="">Cliente</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="service_id" required><option value="">Serviço</option><?php foreach($services as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="professional_id"><option value="">Qualquer profissional</option><?php foreach($professionals as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" type="date" name="preferred_date"></div><div class="col-md-2"><select class="form-select" name="period"><option value="any">Qualquer horário</option><option value="morning">Manhã</option><option value="afternoon">Tarde</option><option value="evening">Noite</option></select></div><div class="col-12"><button class="btn btn-primary">Adicionar à lista</button></div></form></div></div>
<div class="row g-3"><?php foreach($entries as $e):?><div class="col-lg-6"><div class="card h-100"><div class="card-body"><div class="d-flex justify-content-between"><div><div class="eyebrow"><?=htmlspecialchars($e['service_name'])?></div><h2 class="h5"><?=htmlspecialchars($e['customer_name'])?></h2><div class="text-secondary"><?=htmlspecialchars($e['professional_name']??'Qualquer profissional')?> · <?=htmlspecialchars($e['period'])?></div></div><form method="post" action="/waitlist/<?=(int)$e['id']?>/cancel"><?=
\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-danger">Remover</button></form></div><hr><strong>Próximos encaixes</strong><?php if($e['suggestions']):?><ul class="mt-2 mb-0"><?php foreach($e['suggestions'] as $s):?><li><?=htmlspecialchars($s)?></li><?php endforeach;?></ul><?php else:?><div class="text-secondary mt-2">Nenhum horário compatível nos próximos 14 dias.</div><?php endif;?></div></div></div><?php endforeach;?><?php if(!$entries):?><div class="col-12"><div class="empty-state">Lista de espera vazia.</div></div><?php endif;?></div>
